function startHeroPreview(){const canvas=$('heroPreview');if(!canvas||previewRenderer)return;previewRenderer=new THREE.WebGLRenderer({canvas,alpha:false,antialias:true,powerPreference:'low-power'});previewRenderer.setPixelRatio(Math.min(devicePixelRatio||1,1.25));previewRenderer.setSize(canvas.clientWidth,canvas.clientHeight,false);previewRenderer.outputColorSpace=THREE.SRGBColorSpace;previewScene=new THREE.Scene();previewScene.background=new THREE.Color(0x101a2d);previewCamera=new THREE.PerspectiveCamera(32,canvas.clientWidth/canvas.clientHeight,.1,50);previewCamera.position.set(0,2.4,9.8);previewCamera.lookAt(0,2,0);previewScene.add(new THREE.HemisphereLight(0xd8eaff,0x282235,2.2));const key=new THREE.DirectionalLight(0xffe2c1,3);key.position.set(-3,7,6);previewScene.add(key);const rim=new THREE.DirectionalLight(0x5c9dff,2);rim.position.set(4,3,-4);previewScene.add(rim);const plinth=new THREE.Mesh(new THREE.CylinderGeometry(1.5,1.7,.2,8),new THREE.MeshStandardMaterial({color:0x314966,metalness:.3,roughness:.4}));plinth.position.y=-.02;previewScene.add(plinth);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.45,.035,6,48),new THREE.MeshBasicMaterial({color:0x75c8ff}));ring.rotation.x=Math.PI/2;ring.position.y=.1;previewScene.add(ring);updateHeroPreview();const resize=()=>{if(!previewRenderer)return;const w=canvas.clientWidth,h=canvas.clientHeight;previewRenderer.setSize(w,h,false);previewCamera.aspect=w/h;previewCamera.updateProjectionMatrix();};window.addEventListener('resize',resize);const clock=new THREE.Clock();const draw=()=>{if(!previewRenderer)return;previewRaf=requestAnimationFrame(draw);if(previewModel){previewModel.rotation.y+=.005;previewModel.userData.mixer?.update(Math.min(clock.getDelta(),.05));}previewRenderer.render(previewScene,previewCamera);};draw();}
