function updateHeroPreview(){if(!previewRenderer||!previewScene)return;const generation=++previewGeneration;if(previewModel){previewScene.remove(previewModel);previewModel=null;}getHeroAsset(selectedHero).then(gltf=>{if(!previewScene||generation!==previewGeneration)return;const model=cloneSkinnedModel(gltf.scene),box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3()),scale=4.2/Math.max(size.y,.01);model.scale.setScalar(scale);const scaled=new THREE.Box3().setFromObject(model),center=scaled.getCenter(new THREE.Vector3());model.position.set(-center.x,-scaled.min.y,-center.z);previewModel=model;previewScene.add(model);const idle=gltf.animations.find(c=>c.name==='Idle');if(idle){const mixer=new THREE.AnimationMixer(model);mixer.clipAction(idle).play();model.userData.mixer=mixer;}}).catch(()=>{$('previewInfo').textContent='Model 3D belum dapat dimuat';});}
