  const towers=[],specs=[['TURUS KECIL',50,2.8,.58,5.5,2.1],['TURUS KECIL',50,3,.62,5.8,2],['TURUS SEDERHANA',80,3.7,.82,7.5,1.8],['TURUS SEDERHANA',80,4,.9,8,1.7],['TERAS BESAR',200,5.4,1.28,11,1.5]],radii=[31,27,22,17,8.5];
  specs.forEach(([kind,hp,height,radius,range,rate],n)=>{const r=radii[n],tx=Math.cos(angle)*r,tz=Math.sin(angle)*r,g=new THREE.Group();g.position.set(tx,0,tz);const teamRing=new THREE.Mesh(new THREE.TorusGeometry(radius*1.55,.11,6,24),new THREE.MeshStandardMaterial({color:t.color,emissive:t.color,emissiveIntensity:.55,roughness:.35}));teamRing.rotation.x=Math.PI/2;teamRing.position.y=.15;g.add(teamRing);const dais=new THREE.Mesh(new THREE.CylinderGeometry(radius*1.2,radius*1.5,.35,8),new THREE.MeshStandardMaterial({color:t.color,roughness:.58,metalness:.12}));dais.position.y=.15;g.add(dais);const coreGem=new THREE.Mesh(new THREE.OctahedronGeometry(radius*.42,1),new THREE.MeshStandardMaterial({color:0xf4f8ff,emissive:t.color,emissiveIntensity:.65,metalness:.25,roughness:.28}));coreGem.position.y=height*.72;g.add(coreGem);scene.add(g);const tower={team:i,index:n,kind,hp,maxHp:hp,x:tx,z:tz,group:g,alive:true,attackAt:0,range,rate,damage:n<2?3:n<4?4:6};tower.healthBar=makeHealthBar(tower,height+.9);g.add(tower.healthBar);towers.push(tower);const towerFile=n===0?'tower-teal.glb':n===1?'tower-ember.glb':n===2?'tower-teal.glb':n===3?'tower-ember.glb':null;if(towerFile)getEnvironmentAsset(towerFile).then(gltf=>{if(!tower.alive||!scene)return;const model=gltf.scene.clone(true),box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3());model.scale.setScalar((height*(n<2?.62:n<4?.82:1.05))/Math.max(size.y,.01));const scaled=new THREE.Box3().setFromObject(model),center=scaled.getCenter(new THREE.Vector3());model.position.set(-center.x,-scaled.min.y,-center.z);model.traverse(o=>{if(o.isMesh){o.castShadow=false;o.receiveShadow=false;if(Array.isArray(o.material))o.material=o.material.map(m=>{const c=m.clone();if(c.color)c.color.multiplyScalar(.7).lerp(new THREE.Color(t.color),.18);return c;});else if(o.material?.color){o.material=o.material.clone();o.material.color.multiplyScalar(.7).lerp(new THREE.Color(t.color),.18);}}});g.add(model);}).catch(()=>{});});
  const road=new THREE.Mesh(new THREE.BoxGeometry(3.6,.1,22),new THREE.MeshStandardMaterial({color:0x746548,roughness:.95}));road.position.set(x*.5,-.01,z*.5);road.rotation.y=angle+Math.PI/2;scene.add(road);
  bases.push({team:i,x,z,towers,eliminated:false,objects:[platform,road]});
  for(const side of [-1,1]){const a=angle+side*.42;for(const d of [13,18,23]){const tx=Math.cos(a)*d,tz=Math.sin(a)*d;addEnvironmentModel('tree_oak.glb',tx,tz,3.35+(d%2)*.3,a);addEnvironmentModel('rock_medium.glb',tx+side*1.8,tz-side*1.4,1.15,a);}}
  const bushMat=new THREE.MeshStandardMaterial({color:0x397a45,roughness:1});for(const side of [-1,1]){const a=angle+side*.22,tx=Math.cos(a)*11.8,tz=Math.sin(a)*11.8;for(let k=0;k<3;k++){const bush=new THREE.Mesh(new THREE.DodecahedronGeometry(.9+Math.random()*.35,0),bushMat);bush.position.set(tx+Math.cos(a+1.57)*k*.65,.6,tz+Math.sin(a+1.57)*k*.65);bush.scale.y=.68;scene.add(bush);world.push(bush);}}
  const camp={team:i,x:Math.cos(angle+.42)*13,z:Math.sin(angle+.42)*13,hp:80,maxHp:80,respawn:0,available:true,cleared:false};jungleCamps.push(camp);const campMesh=new THREE.Group();campMesh.position.set(camp.x,0,camp.z);const stump=new THREE.Mesh(new THREE.DodecahedronGeometry(.9,0),new THREE.MeshStandardMaterial({color:0x56604e,roughness:.95}));stump.position.y=.48;campMesh.add(stump);const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.48,1),new THREE.MeshStandardMaterial({color:0xd69bff,emissive:0x783bff,emissiveIntensity:1.35,metalness:.15,roughness:.2}));crystal.position.y=1.27;campMesh.add(crystal);for(let k=0;k<3;k++){const shard=new THREE.Mesh(new THREE.ConeGeometry(.18,.72,5),new THREE.MeshStandardMaterial({color:0x9f69ec,emissive:0x5426aa,emissiveIntensity:.55,roughness:.3}));const a=k*Math.PI*2/3;shard.position.set(Math.cos(a)*.65,.48,Math.sin(a)*.65);campMesh.add(shard);}camp.mesh=campMesh;scene.add(campMesh);world.push(campMesh);
