function initScene(){
  const canvas=$('world');renderer=new THREE.WebGLRenderer({canvas,antialias:false,alpha:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1));renderer.setSize(canvas.clientWidth,canvas.clientHeight,false);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.setClearColor(0x101a21);
  scene=new THREE.Scene();scene.background=new THREE.Color(0x101a21);scene.fog=new THREE.Fog(0x101a21,55,100);
  camera=new THREE.PerspectiveCamera(48,canvas.clientWidth/canvas.clientHeight,.1,130);camera.position.set(0,34,40);
  scene.add(new THREE.HemisphereLight(0xbfdcff,0x263246,2.1));const sun=new THREE.DirectionalLight(0xffffff,2.2);sun.position.set(-18,35,22);scene.add(sun);
  const floor=new THREE.Mesh(new THREE.CylinderGeometry(36,36,.6,5),new THREE.MeshStandardMaterial({color:0x355a43,roughness:1}));floor.position.y=-.35;floor.rotation.y=Math.PI/5;scene.add(floor);
  const inner=new THREE.Mesh(new THREE.CylinderGeometry(8.4,8.4,.12,12),new THREE.MeshStandardMaterial({color:0x347e9a,roughness:.25,metalness:.25,transparent:true,opacity:.82}));inner.position.y=-.02;scene.add(inner);
  const river=new THREE.Mesh(new THREE.RingGeometry(8.25,9.4,48),new THREE.MeshStandardMaterial({color:0x48b6d0,roughness:.22,metalness:.15,transparent:true,opacity:.75,side:THREE.DoubleSide}));river.rotation.x=-Math.PI/2;river.position.y=.02;scene.add(river);
  const centerIsle=new THREE.Mesh(new THREE.CylinderGeometry(3.8,4.5,.18,10),new THREE.MeshStandardMaterial({color:0x435b42,roughness:1}));centerIsle.position.y=.1;scene.add(centerIsle);
  const core=new THREE.Mesh(new THREE.OctahedronGeometry(1.5,0),new THREE.MeshStandardMaterial({color:0xc5ffdd,emissive:0x42a879,emissiveIntensity:.8,roughness:.25}));core.position.y=1.35;scene.add(core);world.push(core);
  for(let i=0;i<5;i++){const a=-Math.PI/2+i*Math.PI*2/5;addEnvironmentModel('river-bridge.glb',Math.cos(a)*8.8,Math.sin(a)*8.8,1.34,a+Math.PI/2,.02);}
  for(let i=0;i<5;i++)addBase(i);
  // CC0 environment pieces form a green forest rim around the lanes, giving
  // the pentagonal five-team map a richer MOBA battlefield silhouette.
  for(let i=0;i<20;i++){const a=(i/20)*Math.PI*2,r=33.3+(i%3)*.55;addEnvironmentModel('tree_oak.glb',Math.cos(a)*r,Math.sin(a)*r,3.55+(i%4)*.16,a);if(i%2===0)addEnvironmentModel('rock_large.glb',Math.cos(a+.12)*(r-.7),Math.sin(a+.12)*(r-.7),1.35,a);}
  // Stone MOBA lanes: shared tile asset, aligned with each base and joined by short river bridges.
  for(let i=0;i<5;i++){const a=-Math.PI/2+i*Math.PI*2/5,yaw=a+Math.PI/2;for(let d=4;d<=32;d+=4){addEnvironmentModel('lane-tile.glb',Math.cos(a)*d,Math.sin(a)*d,.24,yaw,-.28);}}
  const onResize=()=>{if(!renderer)return;const w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();};window.addEventListener('resize',onResize);
}
function placeUnits(){units=[];minions=[];remoteUnits.clear();bases.forEach(b=>{b.eliminated=false;b.towers.forEach(t=>{t.hp=t.maxHp;t.alive=true;t.group.visible=true;t.attackAt=0;drawHealthBar(t);});});human=null;
  if(arenaIdentity){const base=bases[selectedTeam],angle=-Math.PI/2+selectedTeam*Math.PI*2/5;human=makeHero(selectedTeam,selectedHero,true,0);human.nick=arenaIdentity.name.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,6)||'PELAJA';scene.remove(human.nameTag);human.nameTag=makeNameTag(human.nick,teams[selectedTeam].css);human.group.add(human.nameTag);human.group.position.set(base.x-Math.cos(angle)*5+Math.cos(angle+Math.PI/2),.1,base.z-Math.sin(angle)*5+Math.sin(angle+Math.PI/2));human.spawnX=human.group.position.x;human.spawnZ=human.group.position.z;units.push(human);}
  else for(let ti=0;ti<5;ti++){const angle=-Math.PI/2+ti*Math.PI*2/5,base=bases[ti];for(let n=0;n<perTeam;n++){const humanHere=ti===selectedTeam&&n===0,heroIndex=humanHere?selectedHero:(n+ti*3)%heroes.length,u=makeHero(ti,heroIndex,humanHere,n),spread=(n-(perTeam-1)/2)*1.05;u.group.position.set(base.x-Math.cos(angle)*(4+n*.45)+Math.cos(angle+Math.PI/2)*spread,.1,base.z-Math.sin(angle)*(4+n*.45)+Math.sin(angle+Math.PI/2)*spread);u.spawnX=u.group.position.x;u.spawnZ=u.group.position.z;units.push(u);if(humanHere)human=u;}}
  jungleCamps.forEach(c=>{c.hp=c.maxHp;c.available=true;c.respawn=0;});}
function startGame(){if(raf)cancelAnimationFrame(raf);stopHeroPreview();$('setup').classList.add('hidden');$('battle').classList.remove('hidden');$('endModal').classList.add('hidden');$('questionModal').classList.add('hidden');if(!renderer)initScene();else for(const u of units)scene.remove(u.group);placeUnits();elapsed=0;paused=false;gameOver=false;energy=100;gold=0;xp=0;playerShieldUntil=0;playerBoostUntil=0;nextWaveAt=3;attackReady=0;skillReady=[0,0,0,0,0];aiAccumulator=0;lastMinimapAt=0;lastFrame=performance.now();updateTeamBars();updatePlayerStats();toast(`${heroes[selectedHero].name} · Pasukan ${teams[selectedTeam].name} · pecahkan CORE`);raf=requestAnimationFrame(loop);loadArenaLeaders();if(arenaIdentity)connectArenaRoom().catch(e=>toast(`Sambungan langsung gagal: ${e.message}`));}
async function connectArenaRoom(){const live=window.quizRealtime;if(!live||!live.active()?.code)throw new Error('Daftar melalui kod sesi guru dahulu.');arenaUid=await live.arenaUid();const spawn={x:human.group.position.x,z:human.group.position.z,rotation:human.group.rotation.y};await live.arenaWrite(arenaSession,'players/'+arenaUid,{team:selectedTeam,hero:selectedHero,nick:human.nick,...spawn,at:Date.now()},true);arenaUnsubs.push(await live.arenaWatch(arenaSession,'players',onArenaPlayers));arenaUnsubs.push(await live.arenaWatch(arenaSession,'events',onArenaEvents));$('arenaConnectionNote').textContent='Firebase langsung · kongsi kod sesi kepada pelajar';}
function onArenaPlayers(players){if(!arenaIdentity||!human)return;const liveIds=new Set(Object.keys(players||{}));const hint=$('hint');if(hint)hint.textContent=`${liveIds.size}/28 pemain dalam talian · menara hanya rosak apabila diserang`;for(const[uid,unit]of remoteUnits){if(liveIds.has(uid))continue;scene?.remove(unit.group);units=units.filter(item=>item!==unit);remoteUnits.delete(uid);}for(const[uid,p]of Object.entries(players||{})){if(uid===arenaUid||!Number.isInteger(p?.team)||!Number.isInteger(p?.hero))continue;let unit=remoteUnits.get(uid);if(!unit){unit=makeHero(p.team,p.hero,false,units.length);unit.nick=String(p.nick||'PELAJA').slice(0,6);scene.remove(unit.nameTag);unit.nameTag=makeNameTag(unit.nick,teams[p.team].css);unit.group.add(unit.nameTag);unit.isRemote=true;unit.spawnX=p.x||0;unit.spawnZ=p.z||0;unit.targetPose={x:p.x||0,z:p.z||0,rotation:p.rotation||0};remoteUnits.set(uid,unit);units.push(unit);getHeroAsset(p.hero).then(gltf=>{if(remoteUnits.get(uid)===unit)attachHeroAsset(unit,gltf);}).catch(()=>{});}if(unit.team!==p.team||unit.hero!==p.hero)continue;unit.targetPose={x:Number(p.x)||0,z:Number(p.z)||0,rotation:Number(p.rotation)||0};unit.hp=Number.isFinite(p.hp)?clamp(p.hp,0,100):100;unit.alive=p.alive!==false;unit.group.visible=unit.alive;drawHealthBar(unit);}}
function onArenaEvents(events){if(!arenaIdentity||!human||!events)return;for(const[uid,items]of Object.entries(events)){for(const[id,event]of Object.entries(items||{})){const key=uid+':'+id;if(seenArenaEvents.has(key))continue;seenArenaEvents.add(key);if(event?.type!=='tower-hit')continue;const tower=bases[event.towerTeam]?.towers[event.towerIndex];if(!tower||tower.team===event.team||frontTower(bases[tower.team])!==tower)continue;damageTower(tower,clamp(Number(event.damage)||1,1,10),{hero:clamp(Number(event.hero)||0,0,9),team:event.team});}}}
function publishPose(){if(!arenaIdentity||!human||!arenaUid||!window.quizRealtime||performance.now()-arenaPoseAt<250)return;arenaPoseAt=performance.now();const p=human.group.position;window.quizRealtime.arenaWrite(arenaSession,'players/'+arenaUid,{team:human.team,hero:human.hero,nick:human.nick,x:clamp(p.x,-39,39),z:clamp(p.z,-39,39),rotation:human.group.rotation.y,hp:human.hp,alive:human.alive,at:Date.now()}).catch(()=>{});}
function publishTowerHit(tower,damage){if(!arenaIdentity||!arenaUid||!window.quizRealtime)return Promise.resolve(false);return window.quizRealtime.arenaPush(arenaSession,'events/'+arenaUid,{type:'tower-hit',team:human.team,hero:human.hero,towerTeam:tower.team,towerIndex:tower.index,damage:clamp(Math.round(damage),1,10),at:Date.now()}).then(()=>true);}
function frontTower(base){return base.towers.find(t=>t.alive)||null;}
function nearestEnemyTower(from,range=Infinity){let best=null,bestD=range;for(const base of bases){if(base.team===from.team||base.eliminated)continue;const tower=frontTower(base);if(!tower)continue;const d=Math.hypot(tower.x-from.group.position.x,tower.z-from.group.position.z);if(d<bestD){best=tower;bestD=d;}}return best;}
function createElementEffect(x,y,z,element,power=1){const colors={fire:0xff6336,water:0x44cfff,wind:0xb8ffc9,earth:0xb78b62,lightning:0xffef55},color=colors[element]||0x9ed9ff,ring=new THREE.Mesh(new THREE.RingGeometry(.28,.48,18),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.95,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.25,z);scene.add(ring);effects.push({mesh:ring,v:new THREE.Vector3(0,.35,0),life:.48,ring:true});
  if(element==='lightning'){const points=[];for(let i=0;i<9;i++)points.push(new THREE.Vector3(x+(Math.random()-.5)*2.5,y+Math.random()*2,z+(Math.random()-.5)*2.5));const geo=new THREE.BufferGeometry().setFromPoints(points),mat=new THREE.LineBasicMaterial({color,transparent:true,opacity:1});const bolt=new THREE.Line(geo,mat);scene.add(bolt);effects.push({mesh:bolt,v:new THREE.Vector3(0,.05,0),life:.2,mat});}
  const count=element==='fire'?6:element==='water'?5:element==='wind'?5:element==='earth'?4:4;for(let i=0;i<count;i++){const geo=element==='earth'?new THREE.TetrahedronGeometry(.16*power,0):element==='water'?new THREE.OctahedronGeometry(.14*power,0):new THREE.IcosahedronGeometry(.12*power,0),mat=new THREE.MeshBasicMaterial({color,transparent:true}),m=new THREE.Mesh(geo,mat),a=Math.random()*Math.PI*2,s=(element==='wind'?2.7:1.1)+Math.random()*1.8;m.position.set(x,.55+Math.random()*1.1,z);scene.add(m);effects.push({mesh:m,v:new THREE.Vector3(Math.cos(a)*s,element==='earth'?.4+Math.random():1+Math.random()*2.3,Math.sin(a)*s),life:.38+Math.random()*.28,mat});}}
function damageTower(tower,damage,source){if(!tower?.alive||frontTower(bases[tower.team])!==tower)return;tower.hp=Math.max(0,tower.hp-damage);drawHealthBar(tower);createElementEffect(tower.x,.5,tower.z,heroes[source?.hero??selectedHero].element,.8);if(tower.hp===0){tower.alive=false;tower.group.visible=false;toast(`${tower.kind} ${teams[tower.team].name} runtuh!`);if(tower.index===4){bases[tower.team].eliminated=true;for(const t of bases[tower.team].towers)t.group.visible=false;toast(`TERAS ${teams[tower.team].name} musnah — pasukan tersingkir!`);}updateTeamBars();}else updateTeamBars();}
function nearestEnemyUnit(from,range=Infinity){let best=null,bestD=range;for(const u of units){if(!u.alive||u.team===from.team)continue;const d=Math.hypot(u.group.position.x-from.group.position.x,u.group.position.z-from.group.position.z);if(d<bestD){best=u;bestD=d;}}for(const m of minions){if(!m.alive||m.team===from.team)continue;const d=Math.hypot(m.group.position.x-from.group.position.x,m.group.position.z-from.group.position.z);if(d<bestD){best=m;bestD=d;}}return best;}
function award(source,target){if(!source?.isHuman)return;gold+=target.isMinion?20:target.isJungle?35:100;xp+=target.isMinion?15:target.isJungle?30:100;updatePlayerStats();}
function damageUnit(target,damage,source){if(!target?.alive)return;if(target.isHuman&&elapsed<playerShieldUntil)damage*=.35;target.hp=Math.max(0,target.hp-damage*(source?.isHuman&&elapsed<playerBoostUntil?1.25:1));drawHealthBar(target);createElementEffect(target.group.position.x,.7,target.group.position.z,heroes[source?.hero??selectedHero].element,.55);if(target.hp<=0){target.alive=false;target.group.visible=false;award(source,target);if(target.isMinion){scene.remove(target.group);minions=minions.filter(m=>m!==target);}else if(target.isJungle){target.camp.cleared=true;target.camp.hp=0;toast('Creep hutan ditewaskan. Tekan BUFF dan jawab betul untuk tuntut kuasa.');}else{target.respawn=7;toast(`${target.nick||heroes[target.hero].name} tumbang · respawn 7s`);}}}
function nearestCamp(from,range=5,cleared=false){return jungleCamps.filter(c=>c.available&&(cleared?c.cleared:!c.cleared)).map(c=>({c,d:Math.hypot(c.x-from.group.position.x,c.z-from.group.position.z)})).filter(x=>x.d<=range).sort((a,b)=>a.d-b.d)[0]?.c||null;}
function hit(){if(!human||gameOver||paused||!human.alive)return;if(elapsed<attackReady){toast(`ATTACK sedia ${Math.ceil(attackReady-elapsed)}s`);return;}attackReady=elapsed+.55;setHeroAnimation(human,heroes[human.hero].attack||'Unarmed_Melee_Attack_Punch_A',false);const target=nearestEnemyUnit(human,5);if(target){human.group.rotation.y=Math.atan2(target.group.position.x-human.group.position.x,target.group.position.z-human.group.position.z);damageUnit(target,target.isMinion?12:5,human);createElementEffect(target.group.position.x,.9,target.group.position.z,heroes[human.hero].element,1.2);toast(`${human.nick} ATTACK · ${target.isMinion?'MINION':target.nick||heroes[target.hero].name}`);return;}const tower=nearestEnemyTower(human,5.8);if(tower){human.group.rotation.y=Math.atan2(tower.x-human.group.position.x,tower.z-human.group.position.z);if(arenaIdentity)publishTowerHit(tower,1);else damageTower(tower,1,human);toast(`${human.nick} ATTACK ${tower.kind} · −1 HP`);return;}const camp=nearestCamp(human,4.5);if(camp){camp.hp-=34;createElementEffect(camp.x,1,camp.z,heroes[human.hero].element,1.1);if(camp.hp<=0){camp.cleared=true;toast('Creep hutan tumbang! Tekan BUFF untuk tuntut kuasa.');}else toast('Serang creep hutan!');return;}toast('Dekati musuh, menara atau creep hutan.');}
function openSkill(which){if(!human||gameOver||paused||!human.alive)return;if(energy<18){toast('Energy belum cukup.');return;}if(elapsed<skillReady[which]){toast(`Kuasa sedia ${Math.ceil(skillReady[which]-elapsed)}s`);return;}if(which===4&&!nearestCamp(human,6,true)){toast('Kalahkan creep hutan dahulu, kemudian tekan BUFF.');return;}activeSkill=which;skillResolved=false;questionIndex=(questionIndex+1)%questions.length;const q=questions[questionIndex],order=[0,1,2,3].sort(()=>Math.random()-.5);activeChoices=order.map(i=>q.a[i]);activeCorrect=order.indexOf(q.c);$('questionText').textContent=q.q;$('questionFeedback').textContent='';$('quizCountdown').textContent='4';answerStarted=elapsed;const area=$('questionOptions');area.replaceChildren();activeChoices.forEach((text,i)=>{const b=document.createElement('button');b.className='answer-choice';b.innerHTML=`<b>${'ABCD'[i]}.</b> ${text}`;b.onclick=()=>answerSkill(i,activeCorrect,b,area);area.append(b);});$('questionModal').classList.remove('hidden');}
function answerSkill(choice,correct,button,area){if(skillResolved)return;if(elapsed-answerStarted>=4){fizzleSkill('Masa habis. Kuasa gagal dilepaskan.');return;}skillResolved=true;const buttons=[...area.querySelectorAll('button')];if(choice!==correct){button.classList.add('bad');buttons.forEach(b=>b.disabled=true);energy=Math.max(0,energy-12);skillReady[activeSkill]=elapsed+6;updatePlayerStats();updateCooldowns();$('questionFeedback').textContent='Salah. Jawapan tidak didedahkan; kuasa gagal.';setTimeout(()=>$('questionModal').classList.add('hidden'),600);return;}buttons.forEach(b=>b.disabled=true);button.classList.add('good');const fast=elapsed-answerStarted<2;energy=Math.max(0,energy-18);if(fast){playerBoostUntil=elapsed+5;playerShieldUntil=elapsed+4;}skillReady[activeSkill]=elapsed+[10,15,24,35][activeSkill-1];$('questionFeedback').textContent=fast?'BETUL PANTAS! OVERCHARGE 125% + SHIELD':'Betul! Kuasa dilepaskan.';castSkill(activeSkill,fast?1.25:1);updatePlayerStats();updateCooldowns();setTimeout(()=>$('questionModal').classList.add('hidden'),650);}
function fizzleSkill(message){if($('questionModal').classList.contains('hidden')||skillResolved)return;skillResolved=true;energy=Math.max(0,energy-12);skillReady[activeSkill]=elapsed+6;$('questionFeedback').textContent=message;updatePlayerStats();updateCooldowns();setTimeout(()=>$('questionModal').classList.add('hidden'),400);}
function castSkill(which,multiplier=1){const profile=heroes[human.hero],element=profile.element;setHeroAnimation(human,profile.cast||'Spellcast_Shoot',false);if(which===4){const camp=nearestCamp(human,7,true);if(!camp){toast('Tiada buff hutan tersedia.');return;}camp.cleared=false;camp.available=false;camp.respawn=40;playerBoostUntil=elapsed+20;playerShieldUntil=elapsed+4;if(profile.special==='heal')human.hp=Math.min(human.maxHp,human.hp+30);if(profile.special==='shield'||profile.special==='guard')playerShieldUntil=elapsed+10;if(profile.special==='dash')playerBoostUntil=elapsed+28;drawHealthBar(human);createElementEffect(camp.x,1,camp.z,element,2);toast(`${profile.skill}: buff ${profile.special} diperoleh!`);return;}let radius=profile.reach[which-1],damage=profile.power[which-1]*multiplier;if(profile.special==='burst')radius*=1.15;if(profile.special==='chain')radius*=1.2;if(profile.special==='burn')damage+=4;if(profile.special==='summon')radius*=1.12;let hits=0;for(const u of [...units,...minions]){if(!u.alive||u.team===human.team)continue;const d=Math.hypot(u.group.position.x-human.group.position.x,u.group.position.z-human.group.position.z);if(d<=radius){damageUnit(u,damage,human);hits++;}}if(profile.special==='chain'&&hits>0){const extra=nearestEnemyUnit(human,radius+3);if(extra&&extra.alive)damageUnit(extra,damage*.45,human);}const tower=nearestEnemyTower(human,radius+2);if(tower&&Math.hypot(tower.x-human.group.position.x,tower.z-human.group.position.z)<=radius+2){const towerDamage=[3,6,10][which-1]*multiplier;if(arenaIdentity)publishTowerHit(tower,towerDamage);else damageTower(tower,towerDamage,human);}if(which===3){if(profile.special==='heal'){human.hp=Math.min(human.maxHp,human.hp+25);playerShieldUntil=elapsed+5;drawHealthBar(human);}else if(profile.special==='shield'||profile.special==='guard')playerShieldUntil=elapsed+8;else if(profile.special==='dash'){const target=nearestEnemyUnit(human,radius+4);if(target){const dx=target.group.position.x-human.group.position.x,dz=target.group.position.z-human.group.position.z,d=Math.max(1,Math.hypot(dx,dz));human.group.position.x+=dx/d*2;human.group.position.z+=dz/d*2;}}}createElementEffect(human.group.position.x,.4,human.group.position.z,element,2.5);toast(`${profile.skill} · ${element.toUpperCase()} · ${hits} musuh kena`);}
function updateCooldowns(){document.querySelectorAll('.skill-btn').forEach(b=>{const n=Number(b.dataset.skill),left=Math.max(0,Math.ceil(skillReady[n]-elapsed));b.classList.toggle('cooldown',left>0);const small=b.querySelector('small');if(small)small.textContent=left?`${left}s`:'4s kuiz';});}
function updatePlayerStats(){if($('playerStats'))$('playerStats').textContent=`❤️ ${human?.alive?Math.ceil(human.hp):0} · ⚡ ${Math.ceil(energy)} · 🪙 ${gold} · XP ${xp}${elapsed<playerShieldUntil?' · SHIELD':''}`;}
function toast(message){$('hint').textContent=message;clearTimeout(feedTimer);feedTimer=setTimeout(()=>{if($('hint'))$('hint').textContent='Lawan hero, minion dan menara musuh.';},2300);}
function updateTeamBars(){const box=$('teamBars');box.innerHTML=bases.map(b=>{const t=teams[b.team],hp=b.towers.reduce((n,x)=>n+x.hp,0),max=b.towers.reduce((n,x)=>n+x.maxHp,0),count=b.towers.filter(x=>x.alive).length,pct=Math.round(hp/max*100),core=b.eliminated?'OUT':'CORE';return`<div class="team-bar"><div class="team-bar-head"><span style="color:${t.css}">${t.name}</span><span>${core} · ${count}/5</span></div><div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${t.css}"></div></div></div>`;}).join('');}
function nearestTowerTarget(base){return frontTower(base);}
function botStep(dt){for(const u of units){if(u.isHuman||u.isRemote||!u.alive)continue;const enemy=nearestEnemyUnit(u,5.2);if(enemy){const dx=enemy.group.position.x-u.group.position.x,dz=enemy.group.position.z-u.group.position.z,d=Math.hypot(dx,dz);u.group.rotation.y=Math.atan2(dx,dz);if(d>1.7){u.group.position.x+=dx/d*dt*2.5;u.group.position.z+=dz/d*dt*2.5;if(elapsed>=u.actionUntil)setHeroAnimation(u,'Running_A',true);}else if(elapsed>u.attackAt){u.attackAt=elapsed+2.1;setHeroAnimation(u,heroes[u.hero].attack,false);damageUnit(enemy,5,u);}}}}
function spawnMinionWaves(){if(elapsed<nextWaveAt)return;nextWaveAt=elapsed+15;for(const base of bases){if(base.eliminated||minions.filter(m=>m.team===base.team&&m.alive).length>=6)continue;const angle=-Math.PI/2+base.team*Math.PI*2/5;for(let n=0;n<3;n++){const group=new THREE.Group(),mat=new THREE.MeshStandardMaterial({color:teams[base.team].color,roughness:.8}),body=new THREE.Mesh(new THREE.BoxGeometry(.72,.9,.58),mat),head=new THREE.Mesh(new THREE.SphereGeometry(.32,7,6),mat);body.position.y=.63;head.position.y=1.25;group.add(body,head);const r=24+n*.5;group.position.set(Math.cos(angle)*r,.1+Math.random()*.1,Math.sin(angle)*r);const minion={team:base.team,group,hp:60,maxHp:60,alive:true,isMinion:true,attackAt:0};group.add(makeHealthBar(minion,2.1));scene.add(group);minions.push(minion);}}}
function minionStep(dt){for(const m of [...minions]){if(!m.alive)continue;const enemy=nearestEnemyUnit(m,2.6);if(enemy){if(elapsed>m.attackAt){m.attackAt=elapsed+2;damageUnit(enemy,4,m);}continue;}const tower=nearestEnemyTower(m,35);if(!tower)continue;const dx=tower.x-m.group.position.x,dz=tower.z-m.group.position.z,d=Math.hypot(dx,dz);if(d>2.5){m.group.position.x+=dx/d*dt*1.6;m.group.position.z+=dz/d*dt*1.6;}}}
function towerInLane(base,tower,target){const a=-Math.PI/2+base.team*Math.PI*2/5,p=target.group.position,along=p.x*Math.cos(a)+p.z*Math.sin(a),across=Math.abs(-p.x*Math.sin(a)+p.z*Math.cos(a)),towerAlong=Math.hypot(tower.x,tower.z),distance=Math.hypot(tower.x-p.x,tower.z-p.z);return distance<=tower.range&&across<5.5&&Math.abs(along-towerAlong)<=tower.range+1;}
function towerStep(){for(const base of bases){if(base.eliminated)continue;for(const tower of base.towers){if(!tower.alive||elapsed<tower.attackAt)continue;const valid=[...units,...minions].filter(u=>u.alive&&u.team!==tower.team&&towerInLane(base,tower,u));const target=valid.find(u=>u.isMinion)||valid.sort((a,b)=>Math.hypot(a.group.position.x-tower.x,a.group.position.z-tower.z)-Math.hypot(b.group.position.x-tower.x,b.group.position.z-tower.z))[0];if(!target)continue;tower.attackAt=elapsed+tower.rate;damageUnit(target,tower.damage,{hero:selectedHero,team:tower.team});}}}
function moveHuman(dt){if(!human?.alive)return;let x=joy.x,z=joy.y;if(keys.has('ArrowLeft')||keys.has('a'))x-=1;if(keys.has('ArrowRight')||keys.has('d'))x+=1;if(keys.has('ArrowUp')||keys.has('w'))z-=1;if(keys.has('ArrowDown')||keys.has('s'))z+=1;const len=Math.hypot(x,z),running=len>.72,speed=running?8.4:4.6;if(len>1){x/=len;z/=len;}if(len>.05){human.group.position.x+=x*dt*speed;human.group.position.z+=z*dt*speed;human.group.rotation.y=Math.atan2(x,z);if(elapsed>=human.actionUntil)setHeroAnimation(human,running?'Running_A':'Walking_A',true);}else if(elapsed>=human.actionUntil)setHeroAnimation(human,'Idle',true);const r=Math.hypot(human.group.position.x,human.group.position.z);if(r>33){human.group.position.x*=33/r;human.group.position.z*=33/r;}}
function drawMinimap(){const c=$('minimap'),ctx=c.getContext('2d'),w=c.width,h=c.height,center=w/2,s=w*.44;ctx.clearRect(0,0,w,h);ctx.fillStyle='#07101de8';ctx.beginPath();ctx.roundRect(2,2,w-4,h-4,18);ctx.fill();ctx.save();ctx.translate(center,center);ctx.strokeStyle='#4ca3bc';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,s*.25,0,Math.PI*2);ctx.stroke();for(let i=0;i<5;i++){const a=-Math.PI/2+i*Math.PI*2/5,x=Math.cos(a)*s,z=Math.sin(a)*s;ctx.strokeStyle='#c0ae7c';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(x,z);ctx.stroke();}for(const b of bases){const a=-Math.PI/2+b.team*Math.PI*2/5;ctx.fillStyle=teams[b.team].css;for(const t of b.towers.filter(t=>t.alive)){ctx.beginPath();ctx.arc(Math.cos(a)*t.x/36*s,Math.sin(a)*t.z/36*s,3.2,0,7);ctx.fill();}ctx.beginPath();ctx.arc(Math.cos(a)*.86*s,Math.sin(a)*.86*s,5,0,7);ctx.fill();}if(human){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(human.group.position.x/36*s,human.group.position.z/36*s,4.5,0,7);ctx.fill();}ctx.restore();}
function updateEffects(dt){for(const fx of [...effects]){fx.life-=dt;fx.mesh.position.addScaledVector(fx.v,dt);fx.v.y-=dt*2;if(fx.ring){const sc=fx.mesh.scale.x+dt*4;fx.mesh.scale.set(sc,sc,sc);fx.mesh.material.opacity=Math.max(0,fx.life*1.8);}else fx.mesh.material.opacity=Math.max(0,fx.life*2);if(fx.life<=0){scene.remove(fx.mesh);fx.mesh.geometry.dispose();fx.mesh.material.dispose();effects=effects.filter(x=>x!==fx);}}}
function loop(now){if(gameOver)return;raf=requestAnimationFrame(loop);const dt=Math.min(.05,(now-lastFrame)/1000||0);lastFrame=now;if(!paused){elapsed+=dt;energy=Math.min(100,energy+dt*2.8);moveHuman(dt);publishPose();for(const remote of remoteUnits.values()){const pose=remote.targetPose;if(!pose)continue;const dx=pose.x-remote.group.position.x,dz=pose.z-remote.group.position.z;remote.group.position.x+=dx*Math.min(1,dt*12);remote.group.position.z+=dz*Math.min(1,dt*12);remote.group.rotation.y=pose.rotation;setHeroAnimation(remote,Math.hypot(dx,dz)>.08?'Running_A':'Idle',true);}if(human&&!human.alive){human.respawn-=dt;if(human.respawn<=0&&!bases[human.team].eliminated){human.alive=true;human.hp=100;drawHealthBar(human);human.group.visible=true;human.group.position.set(human.spawnX,.1,human.spawnZ);toast('Respawn! Hero kembali ke markas.');}}for(const u of units)if(!u.isHuman&&!u.isRemote&&!u.alive){u.respawn-=dt;if(u.respawn<=0&&!bases[u.team].eliminated){u.alive=true;u.hp=u.maxHp;drawHealthBar(u);u.group.visible=true;u.group.position.set(u.spawnX,.1,u.spawnZ);}}for(const c of jungleCamps)if(c.respawn>0){c.respawn-=dt;if(c.respawn<=0){c.available=true;c.cleared=false;c.hp=c.maxHp;}}aiAccumulator+=dt;if(aiAccumulator>=.14){const aiDt=Math.min(aiAccumulator,.22);aiAccumulator=0;spawnMinionWaves();botStep(aiDt);minionStep(aiDt);towerStep();}if(!$('questionModal').classList.contains('hidden')){$('quizCountdown').textContent=Math.max(0,4-Math.floor(elapsed-answerStarted));$('quizBar').style.transform=`scaleX(${Math.max(0,1-(elapsed-answerStarted)/4)})`;if(elapsed-answerStarted>=4)fizzleSkill('Masa habis. Kuasa gagal dilepaskan.');}}
  energy=Math.min(100,energy+dt*.65);$('clock').textContent='∞';updateCooldowns();updatePlayerStats();if(Math.floor(elapsed)%2===0&&Math.floor(elapsed)!==Math.floor(elapsed-dt))updateTeamBars();units.forEach(u=>u.mixer?.update(dt));
  if(human){const p=human.group.position,target=new THREE.Vector3(p.x+1,20,p.z+13);camera.position.lerp(target,.075);camera.lookAt(p.x,1.2,p.z);}world.forEach(o=>{if(o.geometry?.type==='OctahedronGeometry')o.rotation.y+=dt*.38;});updateEffects(dt);if(now-lastMinimapAt>200){drawMinimap();lastMinimapAt=now;}renderer.render(scene,camera);const alive=bases.filter(b=>!b.eliminated);if(alive.length<=1)finishGame(alive);}
function towerHp(base){return base.towers.reduce((sum,t)=>sum+t.hp,0);}
function finishGame(alive){gameOver=true;cancelAnimationFrame(raf);const ranked=[...bases].sort((a,b)=>Number(b.eliminated)-Number(a.eliminated)||towerHp(b)-towerHp(a));$('winnerTitle').textContent=`🏆 Pasukan ${teams[(alive[0]||ranked[ranked.length-1]).team].name} menang!`;$('finalTeams').innerHTML=ranked.map((b,i)=>`<div class="final-team"><b style="color:${teams[b.team].css}">${b.eliminated?'Tersingkir':`#${ranked.length-i} ${teams[b.team].name}`}</b><span>${b.eliminated?'CORE musnah':`CORE berdiri · ${Math.round(towerHp(b))} HP`}</span></div>`).join('');$('endModal').classList.remove('hidden');}
function resetGame(){for(const u of units)scene?.remove(u.group);for(const m of minions)scene?.remove(m.group);units=[];minions=[];bases.forEach(b=>{b.objects.forEach(o=>scene?.remove(o));b.towers.forEach(t=>scene?.remove(t.group));});bases=[];jungleCamps=[];for(const o of world)scene?.remove(o);world=[];for(const fx of effects)scene?.remove(fx.mesh);effects=[];if(renderer){renderer.dispose();renderer.forceContextLoss();renderer=null;scene=null;camera=null;}human=null;skillReady=[0,0,0,0,0];attackReady=0;questionIndex=-1;$('battle').classList.add('hidden');$('endModal').classList.add('hidden');$('questionModal').classList.add('hidden');$('setup').classList.remove('hidden');startHeroPreview();}
$('startBtn').onclick=startGame;$('attackBtn').onclick=hit;document.querySelectorAll('.skill-btn').forEach(b=>b.onclick=()=>openSkill(Number(b.dataset.skill)));$('againBtn').onclick=resetGame;
const joyPad=$('joystick'),knob=$('knob');let pointer=null;function joyMove(e){if(pointer!==e.pointerId)return;const r=joyPad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,len=Math.hypot(dx,dy),s=len>max?max/len:1;joy.x=clamp(dx*s/max,-1,1);joy.y=clamp(dy*s/max,-1,1);knob.style.transform=`translate(${joy.x*max}px,${joy.y*max}px)`;}joyPad.addEventListener('pointerdown',e=>{pointer=e.pointerId;joyPad.setPointerCapture(pointer);joyMove(e);});joyPad.addEventListener('pointermove',joyMove);function joyEnd(){pointer=null;joy={x:0,y:0};knob.style.transform='translate(0,0)';}joyPad.addEventListener('pointerup',joyEnd);joyPad.addEventListener('pointercancel',joyEnd);
window.addEventListener('keydown',e=>{const k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();keys.add(k);if(k===' '&&!e.repeat)hit();});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));$('pauseBtn').onclick=()=>{paused=!paused;$('pauseBtn').textContent=paused?'Sambung':'Jeda';toast(paused?'Permainan dijeda':'Permainan disambung');};
